package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.DosFileAttributes;
import java.nio.file.attribute.PosixFileAttributes;
import java.util.Map;

import org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream;
import org.junit.jupiter.api.Test;

final class Bzip2FileSystemProviderMutaGate1Test {
  @Test
  void readAttributes_unsupportedAttributesType_throwsUnsupportedOperationWithTypeName() throws IOException {
    Path bzPath = Files.createTempFile("tarballfs-mutagate-", ".bz2");
    try {
      byte[] data = "hello".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(bzPath);
          BZip2CompressorOutputStream bzOut = new BZip2CompressorOutputStream(out)) {
        bzOut.write(data);
      }

      Bzip2FileSystemProvider provider = new Bzip2FileSystemProvider();
      URI uri = URI.create("bzip2:" + bzPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path root = fs.getPath("/");
        Path child = fs.getPath("/", bzPath.getFileName().toString());

        UnsupportedOperationException posix =
            assertThrows(
                UnsupportedOperationException.class,
                () -> provider.readAttributes(child, PosixFileAttributes.class));
        assertEquals(
            "Unsupported attributes type: " + PosixFileAttributes.class.getName(), posix.getMessage());

        UnsupportedOperationException dos =
            assertThrows(
                UnsupportedOperationException.class,
                () -> provider.readAttributes(root, DosFileAttributes.class));
        assertEquals(
            "Unsupported attributes type: " + DosFileAttributes.class.getName(), dos.getMessage());
      }
    } finally {
      Files.deleteIfExists(bzPath);
    }
  }
}

