import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.io.OutputStream;
import java.net.URI;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Map;
import java.util.Set;

import org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream;
import org.junit.jupiter.api.Test;

final class Bzip2FileSystemProviderMutaGate6Test {
  @Test
  void newFileChannel_reportsSizeAndPosition_andSupportsRepositioning() throws IOException {
    Path bzPath = Files.createTempFile("tarballfs-test-", ".bz2");
    try {
      byte[] data = "hello".getBytes(StandardCharsets.UTF_8);
      try (OutputStream out = Files.newOutputStream(bzPath);
          BZip2CompressorOutputStream bzOut = new BZip2CompressorOutputStream(out)) {
        bzOut.write(data);
      }

      Bzip2FileSystemProvider provider = new Bzip2FileSystemProvider();
      URI uri = URI.create("bzip2:" + bzPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path p = fs.getPath("/", bzPath.getFileName().toString());
        try (FileChannel ch = provider.newFileChannel(p, Set.of(StandardOpenOption.READ))) {
          assertTrue(ch.isOpen());
          assertEquals(5L, ch.size());
          assertEquals(0L, ch.position());

          ByteBuffer buf = ByteBuffer.allocate(16);
          int n = ch.read(buf);
          assertEquals(5, n);
          assertEquals(5L, ch.position());

          buf.clear();
          assertEquals(-1, ch.read(buf));

          ch.position(1);
          assertEquals(1L, ch.position());
          buf.clear();
          int m = ch.read(buf);
          assertEquals(4, m);
          buf.flip();
          assertEquals("ello", StandardCharsets.UTF_8.decode(buf).toString());
        }
      }
    } finally {
      Files.deleteIfExists(bzPath);
    }
  }
}

