import java.nio.file.FileSystem;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import org.apache.commons.compress.compressors.bzip2.BZip2CompressorOutputStream;
import org.junit.jupiter.api.Test;

final class Bzip2FileSystemProviderMutaGate8Test {
  @Test
  void newDirectoryStream_appliesFilterToRootEntry() throws IOException {
    Path dir = Files.createTempDirectory("tarballfs-bz2-filter-");
    Path bzPath = dir.resolve("filtered.bz2");
    try {
      try (OutputStream out = Files.newOutputStream(bzPath);
          BZip2CompressorOutputStream bzOut = new BZip2CompressorOutputStream(out)) {
        bzOut.write("hello".getBytes(StandardCharsets.UTF_8));
      }

      Bzip2FileSystemProvider provider = new Bzip2FileSystemProvider();
      URI uri = URI.create("bzip2:" + bzPath.toAbsolutePath());
      try (FileSystem fs = provider.newFileSystem(uri, Map.of())) {
        Path root = fs.getPath("/");

        List<String> seen = new ArrayList<>();
        DirectoryStream.Filter<Path> acceptAll =
            p -> {
              seen.add(p.getFileName().toString());
              return true;
            };
        List<String> accepted = new ArrayList<>();
        try (DirectoryStream<Path> ds = provider.newDirectoryStream(root, acceptAll)) {
          for (Path p : ds) {
            accepted.add(p.getFileName().toString());
          }
        }
        assertEquals(List.of("filtered.bz2"), accepted);
        assertEquals(List.of("filtered.bz2"), seen);

        DirectoryStream.Filter<Path> rejectAll = p -> false;
        try (DirectoryStream<Path> ds = provider.newDirectoryStream(root, rejectAll)) {
          assertFalse(ds.iterator().hasNext());
        }

        try (DirectoryStream<Path> ds = Files.newDirectoryStream(root, "*.nomatch")) {
          assertTrue(!ds.iterator().hasNext());
        }
      }
    } finally {
      Files.deleteIfExists(bzPath);
      Files.deleteIfExists(dir);
    }
  }
}
